# owner: platform
import unittest

from rosterkit.contacts import contact_rows
from rosterkit.errors import ProjectError
from rosterkit.models import Student


def make(ident, last, first, sect="A", mail="x@y.org"):
    return Student(ident, last, first, sect, mail)


class ContactRowsTests(unittest.TestCase):
    def test_rows_are_sorted_by_name(self):
        rows = contact_rows([
            make("2", "Young", "Zed"),
            make("1", "Abel", "Amy"),
        ])
        self.assertTrue(rows[0].startswith("Abel, Amy"))
        self.assertTrue(rows[1].startswith("Young, Zed"))

    def test_columns_line_up(self):
        rows = contact_rows([
            make("1", "Li", "Bo", "A", "bo@x.org"),
            make("2", "Hernandez", "Ana", "B", "ana@x.org"),
        ])
        self.assertEqual(
            rows,
            [
                "Hernandez, Ana  B  ana@x.org",
                "Li, Bo          A  bo@x.org",
            ],
        )

    def test_missing_email_names_the_student(self):
        stud = make("1", "Abel", "Amy", mail=None)
        with self.assertRaises(ProjectError) as ctx:
            contact_rows([make("2", "Bee", "Bo"), stud])
        self.assertIn("Abel, Amy", str(ctx.exception))

    def test_blank_email_is_missing(self):
        stud = make("1", "Abel", "Amy", mail="")
        with self.assertRaises(ProjectError):
            contact_rows([stud])

    def test_empty_list_raises(self):
        with self.assertRaises(ProjectError):
            contact_rows([])


if __name__ == "__main__":
    unittest.main()
